1	package events
2	
3	import (
4		"errors"
5		"strings"
6		"time"
7	)
8	
9	// maxCompareSegments caps how many segments a single comparison may split
10	// either window into. Requests needing more are rejected rather than
11	// truncated, so the response always covers the windows completely.
12	const maxCompareSegments = 10000
13	
14	// CompareQuery selects two equal-length, half-open windows [Since, Until) and
15	// [BaselineSince, BaselineUntil) and divides them into intervals of Step,
16	// keeping only events that pass the same optional service, severity, and
17	// label filters Query uses.
18	type CompareQuery struct {
19		Service       string
20		Severity      string
21		Labels        map[string]string
22		BaselineSince time.Time
23		BaselineUntil time.Time
24		Since         time.Time
25		Until         time.Time
26		Step          time.Duration
27	}
28	
29	// CompareSegment is one step-aligned slice of both windows, ordered from each
30	// window's start. Counts include segment start instants and exclude segment
31	// end instants; the final segment ends exactly at the window end even when
32	// that is short of a full step.
33	type CompareSegment struct {
34		BaselineStart    time.Time
35		BaselineEnd      time.Time
36		ObservationStart time.Time
37		ObservationEnd   time.Time
38		BaselineCount    int
39		ObservationCount int
40	}
41	
42	// CompareResult holds the aggregate change between two windows plus every
43	// aligned segment. Ratio is the relative change (observation minus baseline
44	// over baseline); it is nil when the baseline total is zero.
45	type CompareResult struct {
46		BaselineTotal    int
47		ObservationTotal int
48		Difference       int
49		Ratio            *float64
50		Segments         []CompareSegment
51	}
52	
53	// Parameter problems a compare request can hit. The HTTP layer maps each to
54	// its own 400 message.
55	var (
56		// ErrCompareStep reports a non-positive step; the HTTP layer bounds it
57		// further to 1..86400 seconds.
58		ErrCompareStep = errors.New("compare step must be positive")
59		// ErrBaselineWindow reports a baseline whose start is not before its end.
60		ErrBaselineWindow = errors.New("baseline window must start before it ends")
61		// ErrObservationWindow reports an observation window whose start is not
62		// before its end.
63		ErrObservationWindow = errors.New("observation window must start before it ends")
64		// ErrWindowLength reports two windows of different lengths.
65		ErrWindowLength = errors.New("compare windows must have equal length")
66		// ErrTooManySegments reports a request that needs more than
67		// maxCompareSegments segments for either side.
68		ErrTooManySegments = errors.New("compare windows require too many segments")
69	)
70	
71	// Compare validates the windows and counts filtered events inside them using
72	// a single read of the timeline, so both sides, both totals, and every
73	// segment reflect one committed snapshot: a batch committed during the call
74	// is either fully present or fully absent.
75	func (t *Timeline) Compare(query CompareQuery) (CompareResult, error) {
76		segments, err := ValidateCompareWindows(query)
77		if err != nil {
78			return CompareResult{}, err
79		}
80	
81		service := strings.TrimSpace(query.Service)
82		severity := strings.ToLower(strings.TrimSpace(query.Severity))
83	
84		baselineCounts := make([]int, len(segments))
85		observationCounts := make([]int, len(segments))
86	
87		t.mu.RLock()
88		for _, event := range t.events {
89			if service != "" && event.Service != service {
90				continue
91			}
92			if severity != "" && event.Severity != severity {
93				continue
94			}
95			if !labelsMatch(event.Labels, query.Labels) {
96				continue
97			}
98			if i, ok := bucketIndex(event.At, query.BaselineSince, query.BaselineUntil, query.Step); ok {
99				baselineCounts[i]++
100			}
101			if i, ok := bucketIndex(event.At, query.Since, query.Until, query.Step); ok {
102				observationCounts[i]++
103			}
104		}
105		t.mu.RUnlock()
106	
107		for i := range segments {
108			segments[i].BaselineCount = baselineCounts[i]
109			segments[i].ObservationCount = observationCounts[i]
110		}
111	
112		result := CompareResult{Segments: segments}
113		for i := range segments {
114			result.BaselineTotal += baselineCounts[i]
115			result.ObservationTotal += observationCounts[i]
116		}
117		result.Difference = result.ObservationTotal - result.BaselineTotal
118		if result.BaselineTotal != 0 {
119			ratio := float64(result.Difference) / float64(result.BaselineTotal)
120			result.Ratio = &ratio
121		}
122		return result, nil
123	}
124	
125	// ValidateCompareWindows enforces a positive step, strictly increasing
126	// windows (baseline first, then observation), equal lengths, and the per-side
127	// segment limit, then returns the aligned segment skeleton. Windows may
128	// overlap and are compared by absolute instant, so time zones are irrelevant.
129	func ValidateCompareWindows(query CompareQuery) ([]CompareSegment, error) {
130		if query.Step <= 0 {
131			return nil, ErrCompareStep
132		}
133		baselineLen := query.BaselineUntil.Sub(query.BaselineSince)
134		observationLen := query.Until.Sub(query.Since)
135		if baselineLen <= 0 {
136			return nil, ErrBaselineWindow
137		}
138		if observationLen <= 0 {
139			return nil, ErrObservationWindow
140		}
141		if baselineLen != observationLen {
142			return nil, ErrWindowLength
143		}
144	
145		// Ceiling division without an addition that could overflow for windows
146		// close to the maximum representable duration.
147		count := baselineLen / query.Step
148		if baselineLen%query.Step != 0 {
149			count++
150		}
151		if count > maxCompareSegments {
152			return nil, ErrTooManySegments
153		}
154	
155		out := make([]CompareSegment, count)
156		for i := range out {
157			baselineStart := query.BaselineSince.Add(query.Step * time.Duration(i))
158			observationStart := query.Since.Add(query.Step * time.Duration(i))
159			baselineEnd := baselineStart.Add(query.Step)
160			if baselineEnd.After(query.BaselineUntil) {
161				baselineEnd = query.BaselineUntil
162			}
163			observationEnd := observationStart.Add(query.Step)
164			if observationEnd.After(query.Until) {
165				observationEnd = query.Until
166			}
167			out[i] = CompareSegment{
168				BaselineStart:    baselineStart,
169				BaselineEnd:      baselineEnd,
170				ObservationStart: observationStart,
171				ObservationEnd:   observationEnd,
172			}
173		}
174		return out, nil
175	}
176	
177	// bucketIndex reports the zero-based segment, measured in whole steps from the
178	// window start, that contains at. The window is half-open: [start, end).
179	// A boundary aligned exactly with a segment start is counted in that segment;
180	// an instant equal to the window end is excluded.
181	func bucketIndex(at, start, end time.Time, step time.Duration) (int, bool) {
182		if at.Before(start) || !at.Before(end) {
183			return 0, false
184		}
185		offset := at.Sub(start)
186		if offset < 0 {
187			return 0, false
188		}
189		return int(offset / step), true
190	}
