305		}
306		q := events.Query{
307			Service:  values.Get("service"),
308			Severity: values.Get("severity"),
309			Labels:   labels,
310		}
311		if raw := values.Get("since"); raw != "" {
312			parsed, err := time.Parse(time.RFC3339Nano, raw)
313			if err != nil {
314				return events.Query{}, errors.New("since must be an RFC3339Nano timestamp")
315			}
316			q.Since = parsed
317		}
318		if raw := values.Get("until"); raw != "" {
319			parsed, err := time.Parse(time.RFC3339Nano, raw)
320			if err != nil {
321				return events.Query{}, errors.New("until must be an RFC3339Nano timestamp")
322			}
323			q.Until = parsed
324		}
325		if !q.Since.IsZero() && !q.Until.IsZero() && q.Since.After(q.Until) {
