346		vs, present := values["limit"]
347		if !present {
348			return defaultPageLimit, nil
349		}
350		if len(vs) != 1 {
351			return 0, errors.New("limit must be an integer from 1 to 1000")
352		}
353		raw := vs[0]
354		if raw == "" || !isDecimal(raw) {
355			return 0, errors.New("limit must be an integer from 1 to 1000")
356		}
357		n, err := strconv.Atoi(raw)
358		if err != nil || n < 1 || n > maxPageLimit {
359			return 0, errors.New("limit must be an integer from 1 to 1000")
360		}
361		return n, nil
362	}
