365		case err := <-waitCh:
366			if err == nil {
367				t.Fatal("second instance must exit non-zero while directory is locked")
368			}
369			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
370				t.Fatalf("second instance must fail non-zero: %v", err)
371			}
372			if !strings.Contains(logs.String(), "in use") {
373				t.Fatalf("error must explain directory is in use:\n%s", logs.String())
374			}
375		case <-time.After(5 * time.Second):
376			second.Process.Kill()
377			t.Fatal("second instance hung instead of failing on the lock")
378		}
379	
380		// The first instance is untouched and keeps serving its data.
381		if got := getEvents(t, first, ""); len(got) != 2 {
382			t.Fatalf("failed takeover must not disturb first instance: %d events", len(got))
383		}
384	
385		// After graceful exit, a new instance can claim the directory.
386		first.signal(t, syscall.SIGTERM)
387		first.waitExit(t, 0)
388		waitTCPPortClosed(t, first.addr)
389		third := startServer(t, dataDir)
390		if got := getEvents(t, third, ""); len(got) != 2 {
391			t.Fatalf("post-exit restart must recover data: %+v", got)
392		}
393		third.signal(t, syscall.SIGTERM)
394		third.waitExit(t, 0)
395	}
