package httpapi

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
)

// previewBounds limits a POST /alerts/preview body to the same size as an
// ingestion request.
const maxGroupLabels = 4

// rawPreviewRequest keeps every member unexamined so presence, null, type,
// and duplicate-key checks can be applied with explicit messages.
type rawPreviewRequest struct {
	Since          *json.RawMessage `json:"since"`
	Until          *json.RawMessage `json:"until"`
	WindowSeconds  *json.RawMessage `json:"window_seconds"`
	Threshold      *json.RawMessage `json:"threshold"`
	TriggerWindows *json.RawMessage `json:"trigger_windows"`
	RecoverWindows *json.RawMessage `json:"recover_windows"`
	Service        *json.RawMessage `json:"service"`
	Severity       *json.RawMessage `json:"severity"`
	Labels         *json.RawMessage `json:"labels"`
	GroupLabels    *json.RawMessage `json:"group_labels"`
}

type previewResponse struct {
	GroupLabels []string         `json:"group_labels"`
	Groups      []previewGroupDTO `json:"groups"`
}

type previewGroupDTO struct {
	Service     string           `json:"service"`
	LabelValues []*string        `json:"label_values"`
	Windows     []previewWindow  `json:"windows"`
	Alerts      []previewAlert   `json:"alerts"`
}

type previewWindow struct {
	Since  string `json:"since"`
	Until  string `json:"until"`
	Count  int    `json:"count"`
	Status string `json:"status"`
}

type previewAlert struct {
	TriggeredAt string  `json:"triggered_at"`
	RecoveredAt *string `json:"recovered_at"`
}

func (h *Handler) previewAlerts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", "POST")
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}
	if h.unavailable() {
		writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
		return
	}

	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}

	query, ok := decodePreviewRequest(w, body)
	if !ok {
		return
	}

	result, perr := h.timeline.PreviewAlerts(query)
	if perr != nil {
		writePreviewError(w, perr)
		return
	}

	groups := make([]previewGroupDTO, 0, len(result.Groups))
	for _, group := range result.Groups {
		windows := make([]previewWindow, len(group.Windows))
